   add(area,'area',label,{icon,children:[0,1,2].map(i=>area+'-finding-'+i)});
   const sources=[{title:'Company application',previewState:'available',sourceType:'Company record',status:'Company supplied',excerpt:'The application describes the team, product, and current progress.',url:'https://pitch-investor-prototype.vercel.app/preview.html#company/application-astergrid/application'},{title:label+' review notes',previewState:'pending',sourceType:'Sample review note',status:'Review pending',excerpt:'The review is in progress; this record has not been independently verified.'},{title:label+' supporting record',previewState:'missing',sourceType:'Sample source request',status:'Not attached',excerpt:'Supporting evidence has not been attached to this sample.'}];
