   for(let i=0;i<2;i++)add(area+'-synthesis-'+i,'synthesis',i?'What still needs to be established':`What the ${label.toLowerCase()} record supports`,{confidence:i?'moderate':'high',children:i?[area+'-signal-1',area+'-signal-2']:[0,1,2].map(i=>area+'-signal-'+i)});
   [`Relevant ${label.toLowerCase()} experience is a starting point`,`${label} readiness needs independent proof`,`The ${label.toLowerCase()} record contains open questions`].forEach((text,i)=>add(area+'-finding-'+i,'finding',text,{area,confidence:i?'low':level(c.confidence),summaryText:m.statement,children:i?[area+'-synthesis-1']:[area+'-synthesis-0',area+'-synthesis-1']}));
