 const sourcePill=(m,id)=>{const n=descendants(m,id,'source').length;return `<button type="button" class="pp-trace-sources-pill" data-trace-pop="sources" data-node="${E(id)}" aria-expanded="false">${n} source${n===1?'':'s'}</button>`;};
